   ["Comunitat Valenciana", "Juanfran Pérez Llorca", "PP en minoría, con apoyo de Vox", "No"],
   ["Extremadura", "María Guardiola", "PP y Vox (desde abril de 2026)", "No"],
   ["Galicia", "Alfonso Rueda", "PP (mayoría absoluta)", "Sí: A Coruña (2025) y Santiago (2026)"],
   ["Illes Balears", "Marga Prohens", "PP en minoría", "No"],
